{"command":"create","path":"/workspace/backend/main.go","file_text":"package main

import (
 "context"
 "crypto/rand"
 "crypto/sha256"
 "encoding/hex"
 "encoding/json"
 "errors"
 "fmt"
 "io"
 "log"
 "net/http"
 "os"
 "path/filepath"
 "strings"
 "time"

 "github.com/jackc/pgx/v5/pgxpool"
)

type App struct { db *pgxpool.Pool; static string }
type User struct { ID, Username, FullName, Role string; Roles []string; AssignedLocation string }
type handler func(http.ResponseWriter,*http.Request,*User,map[string]any) (any,int,*apiError)
type apiError struct { Status int; Code, Message string }

func main(){
 ctx:=context.Background(); db,err:=pgxpool.New(ctx,os.Getenv("DATABASE_URL")); if err!=nil { log.Fatal(err) }
 if err=db.Ping(ctx); err!=nil { log.Fatal(err) }
 a:=&App{db:db,static:"/workspace/frontend/dist"}; if err=a.bootstrapAdmin(ctx); err!=nil { log.Fatal(err) }
 mux:=http.NewServeMux(); mux.HandleFunc("/ready",a.ready); mux.HandleFunc("/api/authenticate-user",a.authenticate)
 mux.HandleFunc("/api/read-sample-state/",a.getSampleState); mux.HandleFunc("/api/read-user/",a.getUser); mux.HandleFunc("/api/events",a.events); mux.HandleFunc("/api/ui/bootstrap",a.bootstrap)
 ops:=map[string]handler{
  "accept-assignment":a.acceptAssignment,"cancel-journey":a.cancelJourney,"check-serviceability":a.checkServiceability,"collect-and-seal-sample":a.collectSeal,
  "configure-capacity":a.configureCapacity,"configure-laboratory-acceptance":a.configureAcceptance,"confirm-handoff":a.confirmHandoff,"confirm-laboratory-receipt":a.confirmReceipt,
  "create-collection-request":a.createRequest,"create-connection":a.createConnection,"create-location":a.createLocation,"create-sample-type":a.createSampleType,"create-user":a.createUser,
  "decline-assignment":a.declineAssignment,"edit-active-plan":a.editPlan,"ingest-presealed-sample":a.ingestPresealed,"initiate-handoff":a.initiateHandoff,"list-role-work":a.listRoleWork,
  "merge-journeys":a.mergeJourneys,"read-journey-plan":a.readJourney,"read-operations-state":a.operations,"read-sample-lifecycle":a.sampleLifecycle,"read-serviceability-snapshot":a.serviceabilitySnapshot,
  "record-handling-checkpoint":a.handlingCheckpoint,"record-laboratory-exception":a.labException,"record-worker-location":a.workerLocation,"report-disruption":a.disruption,
  "reroute-journey":a.reroute,"search-audit-trail":a.searchAudit,"select-active-role":a.selectRole,"set-connection-status":a.setConnectionStatus,"set-location-function-status":a.setFunctionStatus,
  "set-location-status":a.setLocationStatus,"set-worker-availability":a.setWorkerAvailability,"split-journey":a.splitJourney,"update-assignment-progress":a.assignmentProgress,
  "update-location":a.updateLocation,"update-sample-type":a.updateSampleType,"update-user-access":a.updateUserAccess,
 }
 for name,h:=range ops { p:="/api/"+name; hh:=h; mux.HandleFunc(p,func(w http.ResponseWriter,r *http.Request){ a.handle(w,r,hh) }) }
 mux.HandleFunc("/",a.frontend)
 srv:=&http.Server{Addr:"127.0.0.1:8080",Handler:securityHeaders(mux),ReadHeaderTimeout:5*time.Second}; log.Printf("LabFlow listening on %s",srv.Addr); log.Fatal(srv.ListenAndServe())
}

func (a *App) bootstrapAdmin(ctx context.Context) error { var n int; if err:=a.db.QueryRow(ctx,"select count(*) from labflow.users").Scan(&n); err!=nil{return err}; if n>0{return nil}; u,p:=os.Getenv("ADMIN_USERNAME"),os.Getenv("ADMIN_PASSWORD"); if u==""||p=="" {return errors.New("ADMIN_USERNAME and ADMIN_PASSWORD required")}; _,err:=a.db.Exec(ctx,"insert into labflow.users(username,password_hash,full_name,roles) values($1,$2,$3,'[\"administrator\"]')",u,hashPassword(p),"System Administrator"); return err }
func hashPassword(p string) string { h:=sha256.Sum256([]byte("labflow:"+p)); return hex.EncodeToString(h[:]) }
func token() string { b:=make([]byte,32); _,_=rand.Read(b); return hex.EncodeToString(b) }
func uuid() string { b:=make([]byte,16); _,_=rand.Read(b); b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; return fmt.Sprintf("%x-%x-%x-%x-%x",b[:4],b[4:6],b[6:8],b[8:10],b[10:]) }
func now() string{return time.Now().UTC().Format(time.RFC3339Nano)}
func securityHeaders(next http.Handler) http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("X-Frame-Options","DENY");w.Header().Set("Referrer-Policy","no-referrer");next.ServeHTTP(w,r)})}
func write(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
func fail(w http.ResponseWriter,status int,code,msg string){write(w,status,map[string]any{"error":msg,"code":code})}
func data(v any) map[string]any{return map[string]any{"data":v}}
func str(m map[string]any,k string) string {v,_:=m[k].(string);return v}
func boolean(m map[string]any,k string,d bool) bool {v,ok:=m[k].(bool);if !ok{return d};return v}
func number(m map[string]any,k string,d float64) float64 {v,ok:=m[k].(float64);if !ok{return d};return v}
func arr(m map[string]any,k string) []any {v,_:=m[k].([]any);if v==nil{return []any{}};return v}
func stringsFrom(v any) []string {a,_:=v.([]any); out:=[]string{};for _,x:=range a{if s,ok:=x.(string);ok{out=append(out,s)}};return out}
func includes(a []string,s string)bool{for _,x:=range a{if x==s{return true}};return false}
func parseTime(v string)(time.Time,error){return time.Parse(time.RFC3339,v)}
func jsonMap(v any) []byte { b,_:=json.Marshal(v); return b }
func nullable(s string)any{if s==""{return nil};return s}

func (a *App) auth(r *http.Request)(*User,*apiError){
 h:=r.Header.Get("Authorization");if !strings.HasPrefix(h,"Bearer "){return nil,&apiError{401,"unauthorized","Authentication required"}}
 var u User; var roles []byte; err:=a.db.QueryRow(r.Context(),`select u.id,u.username,u.full_name,u.roles,s.active_role,coalesce(u.assigned_location_id::text,'') from labflow.sessions s join labflow.users u on u.id=s.user_id where s.token=$1 and s.expires_at>now() and u.active`,strings.TrimPrefix(h,"Bearer ")).Scan(&u.ID,&u.Username,&u.FullName,&roles,&u.Role,&u.AssignedLocation)
 if err!=nil{return nil,&apiError{401,"unauthorized","Invalid or expired session"}};_ = json.Unmarshal(roles,&u.Roles);return &u,nil
}
func (a *App) handle(w http.ResponseWriter,r *http.Request,h handler){
 if r.Method!=http.MethodPost{fail(w,405,"method_not_allowed","Method not allowed");return}; u,e:=a.auth(r);if e!=nil{fail(w,e.Status,e.Code,e.Message);return}
 var in map[string]any; dec:=json.NewDecoder(io.LimitReader(r.Body,1<<20));if err:=dec.Decode(&in);err!=nil{fail(w,400,"invalid_json","Invalid JSON body");return}
 out,status,e:=h(w,r,u,in);if e!=nil{a.audit(r.Context(),u,e.Code,"request",r.URL.Path,false,map[string]any{"error":e.Message});fail(w,e.Status,e.Code,e.Message);return};write(w,status,data(out))
}
func (a *App) require(u *User,roles ...string)*apiError{if u.Role==""{return &apiError{409,"role_not_selected","Select an active role"}};for _,r:=range roles{if u.Role==r||u.Role=="administrator"&&r=="dispatcher"{return nil}};return &apiError{403,"forbidden","Active role is not permitted"}}
