func (a *App) sampleLifecycle(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){sid:=str(in,"sampleId");if !a.allowedSample(r.Context(),u,sid){return nil,0,&apiError{403,"forbidden","Sample is outside active role scope"}};var status string;var sealed bool;var journey,holder,received *string;var ex,loc []byte;var at *time.Time;if a.db.QueryRow(r.Context(),"select status,sealed,active_journey_id,current_holder_id,received_laboratory_id,exception,latest_location,location_recorded_at from labflow.samples where id=$1",sid).Scan(&status,&sealed,&journey,&holder,&received,&ex,&loc,&at)!=nil{return nil,0,&apiError{404,"not_found","Sample not found"}};completed:=[]string{};rows,_:=a.db.Query(r.Context(),"select id from labflow.assignments where sample_id=$1 and status='completed'",sid);if rows!=nil{for rows.Next(){var id string;_=rows.Scan(&id);completed=append(completed,id)};rows.Close()};m:=map[string]any{"sampleId":sid,"status":status,"sealed":sealed,"completedLegIds":completed,"activeReplacementPlanIds":[]string{},"timeline":a.timeline(r.Context(),"sample",sid),"locationStale":at==nil||time.Since(*at)>15*time.Minute};if journey!=nil{m["activeJourneyId"]=*journey};if holder!=nil{m["currentHolderId"]=*holder};if received!=nil{m["receivedLaboratoryId"]=*received};if len(ex)>0{m["exception"]=decode(ex)};if len(loc)>0{m["latestLocation"]=decode(loc)};if at!=nil{m["locationRecordedAt"]=at.Format(time.RFC3339)};var hid string;var hand []byte;if a.db.QueryRow(r.Context(),`select id,jsonb_build_object('handoffId',id,'senderId',sender_id,'receiverId',receiver_id,'status',status,'senderConfirmed',sender_confirmed,'receiverConfirmed',receiver_confirmed) from labflow.handoffs where sample_id=$1 and status='pending'`,sid).Scan(&hid,&hand)==nil{m["pendingHandoffId"]=hid;m["pendingHandoff"]=decode(hand)};return m,200,nil}
func (a *App) listRoleWork(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){role:=str(in,"role");if role==""{role=u.Role};if role!=u.Role{return nil,0,&apiError{403,"forbidden","Work role must match active role"}};pending,inprogress,completed:=[]any{},[]any{},[]any{};if role=="requester"{for _,x:=range a.requesterSamples(r,u){m:=x.(map[string]any);switch m["status"]{case "received","cancelled":completed=append(completed,m);case "planned","exception":pending=append(pending,m);default:inprogress=append(inprogress,m)}}}else if role=="dispatcher"||role=="administrator"{rows,_:=a.db.Query(r.Context(),"select id,status,route_mode,plan_version,sample_ids,estimated_delivery_at from labflow.journeys order by created_at desc");if rows!=nil{for rows.Next(){var id,status,mode string;var ver int;var ids []byte;var eta *time.Time;_=rows.Scan(&id,&status,&mode,&ver,&ids,&eta);m:=map[string]any{"kind":"journey","journeyId":id,"status":status,"routeMode":mode,"planVersion":ver,"sampleIds":decode(ids),"estimatedDeliveryAt":time.Now().UTC().Format(time.RFC3339),"assignmentCount":0,"history":a.timeline(r.Context(),"journey",id)};if eta!=nil{m["estimatedDeliveryAt"]=eta.Format(time.RFC3339)};if status=="completed"||status=="cancelled"{completed=append(completed,m)}else{inprogress=append(inprogress,m)}};rows.Close()}}else{rows,_:=a.db.Query(r.Context(),`select id,sample_id,kind,status,journey_id,from_location_id,to_location_id,sequence,offer_expires_at,node_id,laboratory_id from labflow.assignments where worker_id=$1 order by created_at desc`,u.ID);if rows!=nil{for rows.Next(){var id,sid,kind,status string;var journey,from,to,node,lab *string;var seq int;var exp *time.Time;_=rows.Scan(&id,&sid,&kind,&status,&journey,&from,&to,&seq,&exp,&node,&lab);m:=map[string]any{"kind":kind,"assignmentId":id,"sampleId":sid,"status":status,"history":a.timeline(r.Context(),"assignment",id)};if journey!=nil{m["journeyId"]=*journey};if from!=nil{m["fromLocationId"]=*from};if to!=nil{m["toLocationId"]=*to};if node!=nil{m["nodeId"]=*node};if lab!=nil{m["laboratoryId"]=*lab};m["sequence"]=seq;if exp!=nil{m["offerExpiresAt"]=exp.Format(time.RFC3339)};if status=="offered"||status=="pending"{pending=append(pending,m)}else if status=="completed"||status=="declined"||status=="cancelled"{completed=append(completed,m)}else{inprogress=append(inprogress,m)}};rows.Close()}};return map[string]any{"pending":pending,"inProgress":inprogress,"completed":completed},200,nil}
func (a *App) searchAudit(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){if e:=a.require(u,"dispatcher");e!=nil{return nil,0,e};limit,offset:=int(number(in,"limit",50)),int(number(in,"offset",0));if limit<1{limit=50};if limit>200{limit=200};order:=str(in,"order");if order==""{order="newest_first"};dir:="desc";if order=="oldest_first"{dir="asc"};where:=`where ($1='' or actor_id=$1) and ($2='' or entity_type=$2) and ($3='' or entity_id=$3) and ($4='' or action=$4) and ($5='' or role=$5) and ($6='' or action ilike '%'||$6||'%' or entity_id ilike '%'||$6||'%')`;args:=[]any{str(in,"actorId"),str(in,"entityType"),str(in,"entityId"),str(in,"action"),str(in,"role"),str(in,"query")};var total int;_=a.db.QueryRow(r.Context(),"select count(*) from labflow.audit "+where,args...).Scan(&total);rows,_:=a.db.Query(r.Context(),"select id,actor_id,role,action,entity_type,entity_id,success,occurred_at,details from labflow.audit "+where+" order by occurred_at "+dir+" limit $7 offset $8",append(args,limit,offset)...);entries:=[]any{};if rows!=nil{for rows.Next(){var id int64;var actor,role,action,typ,eid string;var success bool;var at time.Time;var raw []byte;_=rows.Scan(&id,&actor,&role,&action,&typ,&eid,&success,&at,&raw);entries=append(entries,map[string]any{"auditId":stringID(id),"actorId":actor,"role":role,"actorRole":role,"action":action,"entityType":typ,"entityId":eid,"success":success,"occurredAt":at.Format(time.RFC3339),"details":decode(raw)})};rows.Close()};out:=map[string]any{"entries":entries,"total":total,"returned":len(entries),"offset":offset,"limit":limit,"order":order,"hasMore":offset+len(entries)<total};if offset+len(entries)<total{out["nextOffset"]=offset+len(entries)};return out,200,nil}
func stringID(n int64)string{const digits="0123456789";if n==0{return "0"};b:=[]byte{};for n>0{b=append([]byte{digits[n%10]},b...);n/=10};return string(b)}
