func (a *App) journeyPlan(r *http.Request,id string)(map[string]any,*apiError){var parent *string;var ver int;var mode,status string;var lab *string;var eta *time.Time;var ids,stops []byte;if a.db.QueryRow(r.Context(),`select parent_id,plan_version,route_mode,status,target_laboratory_id,estimated_delivery_at,sample_ids,stops from labflow.journeys where id=$1`,id).Scan(&parent,&ver,&mode,&status,&lab,&eta,&ids,&stops)!=nil{return nil,&apiError{404,"not_found","Journey not found"}};legs:=[]any{};workers:=[]string{};collections,nodes,labs:=[]string{},[]string{},[]string{};rows,_:=a.db.Query(r.Context(),`select id,sequence,status,from_location_id,to_location_id,worker_id,sample_id,kind from labflow.assignments where journey_id=$1 order by sequence,created_at`,id);if rows!=nil{for rows.Next(){var aid,st,sid,kind string;var seq int;var from,to,worker *string;_=rows.Scan(&aid,&seq,&st,&from,&to,&worker,&sid,&kind);m:=map[string]any{"assignmentId":aid,"sequence":seq,"status":st,"sampleId":sid};if from!=nil{m["fromLocationId"]=*from};if to!=nil{m["toLocationId"]=*to};if worker!=nil{m["workerId"]=*worker;workers=append(workers,*worker)};legs=append(legs,m);switch kind{case "collection":collections=append(collections,aid);case "node":nodes=append(nodes,aid);case "laboratory":labs=append(labs,aid)}};rows.Close()};m:=map[string]any{"journeyId":id,"planVersion":ver,"routeMode":mode,"status":status,"sampleIds":decode(ids),"orderedStops":decode(stops),"legs":legs,"assignedWorkerIds":workers,"collectionAssignmentIds":collections,"nodeAssignmentIds":nodes,"laboratoryAssignmentIds":labs};if parent!=nil{m["parentJourneyId"]=*parent};if eta!=nil{m["estimatedDeliveryAt"]=eta.Format(time.RFC3339)};return m,nil}
func (a *App) readJourney(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){id:=str(in,"journeyId");if u.Role!="dispatcher"&&u.Role!="administrator"{var allowed bool;if u.Role=="requester"{_ =a.db.QueryRow(r.Context(),`select exists(select 1 from labflow.samples where active_journey_id=$1 and requester_id=$2)`,id,u.ID).Scan(&allowed)}else{_ =a.db.QueryRow(r.Context(),`select exists(select 1 from labflow.assignments where journey_id=$1 and worker_id=$2)`,id,u.ID).Scan(&allowed)};if !allowed{return nil,0,&apiError{403,"forbidden","Journey is outside active role scope"}}};p,e:=a.journeyPlan(r,id);if e!=nil{return nil,0,e};if u.Role!="dispatcher"&&u.Role!="administrator"{if u.Role=="requester"{delete(p,"assignedWorkerIds");delete(p,"collectionAssignmentIds");delete(p,"nodeAssignmentIds");delete(p,"laboratoryAssignmentIds")}else{p["scope"]="assigned_legs";ids:=[]string{};legs:=[]any{};for _,x:=range p["legs"].([]any){m:=x.(map[string]any);if m["workerId"]==u.ID{ids=append(ids,m["assignmentId"].(string));legs=append(legs,m)}};p["assignmentIds"]=ids;p["legs"]=legs;delete(p,"sampleIds")}};return p,200,nil}
func (a *App) checkVersion(r *http.Request,id string,expected int)(int,*apiError){var ver int;var status string;if a.db.QueryRow(r.Context(),"select plan_version,status from labflow.journeys where id=$1",id).Scan(&ver,&status)!=nil{return 0,&apiError{404,"not_found","Journey not found"}};if ver!=expected{return 0,&apiError{409,"stale_plan","Journey plan version changed"}};if status=="cancelled"||status=="completed"{return 0,&apiError{409,"inactive_plan","Journey is no longer active"}};return ver,nil}
func (a *App) editPlan(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){if e:=a.require(u,"dispatcher");e!=nil{return nil,0,e};if e:=needKey(in);e!=nil{return nil,0,e};id:=str(in,"journeyId");expected:=int(number(in,"expectedPlanVersion",0));if _,e:=a.checkVersion(r,id,expected);e!=nil{return nil,0,e};change:=str(in,"changeType");if change==""{return nil,0,&apiError{400,"invalid_plan","Change type is required"}};tag,_:=a.db.Exec(r.Context(),"update labflow.journeys set plan_version=plan_version+1 where id=$1 and plan_version=$2",id,expected);if tag.RowsAffected()==0{return nil,0,&apiError{409,"stale_plan","Journey plan version changed"}};a.audit(r.Context(),u,"journey_plan_edited","journey",id,true,map[string]any{"changeType":change,"changes":in["changes"]});p,e:=a.journeyPlan(r,id);return p,201,e}
func (a *App) cancelJourney(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){if e:=a.require(u,"dispatcher");e!=nil{return nil,0,e};if e:=needKey(in);e!=nil{return nil,0,e};id:=str(in,"journeyId");if _,e:=a.checkVersion(r,id,int(number(in,"expectedPlanVersion",0)));e!=nil{return nil,0,e};var ids []byte;tx,_:=a.db.Begin(r.Context());if tx.QueryRow(r.Context(),"update labflow.journeys set status='cancelled',plan_version=plan_version+1 where id=$1 returning sample_ids",id).Scan(&ids)!=nil{return nil,0,&apiError{404,"not_found","Journey not found"}};_,_=tx.Exec(r.Context(),"update labflow.assignments set status='cancelled' where journey_id=$1 and status not in ('completed')",id);_,_=tx.Exec(r.Context(),"update labflow.samples set status='cancelled' where active_journey_id=$1 and status not in ('received')",id);_ =tx.Commit(r.Context());a.audit(r.Context(),u,"journey_cancelled","journey",id,true,map[string]any{"reason":str(in,"reason")});return map[string]any{"journeyId":id,"status":"cancelled","sampleIds":decode(ids)},201,nil}
func (a *App) reroute(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){if e:=a.require(u,"dispatcher");e!=nil{return nil,0,e};if e:=needKey(in);e!=nil{return nil,0,e};id:=str(in,"journeyId");ver:=int(number(in,"expectedPlanVersion",0));if _,e:=a.checkVersion(r,id,ver);e!=nil{return nil,0,e};old,e:=a.journeyPlan(r,id);if e!=nil{return nil,0,e};replacement:=uuid();ids:=old["sampleIds"];stops:=old["orderedStops"];var mode string=old["routeMode"].(string);var eta any=nil;if v,ok:=old["estimatedDeliveryAt"];ok{eta=v};tx,_:=a.db.Begin(r.Context());tag,_:=tx.Exec(r.Context(),"update labflow.journeys set status='replaced',plan_version=plan_version+1 where id=$1 and plan_version=$2",id,ver);if tag.RowsAffected()==0{return nil,0,&apiError{409,"stale_plan","Journey plan version changed"}};_,_=tx.Exec(r.Context(),`insert into labflow.journeys(id,parent_id,route_mode,status,estimated_delivery_at,sample_ids,stops) values($1,$2,$3,'planned',$4,$5,$6)`,replacement,id,mode,eta,jsonMap(ids),jsonMap(stops));_,_=tx.Exec(r.Context(),`update labflow.assignments set journey_id=$2 where journey_id=$1 and status not in ('completed')`,id,replacement);_,_=tx.Exec(r.Context(),"update labflow.samples set active_journey_id=$2 where active_journey_id=$1",id,replacement);_ =tx.Commit(r.Context());rp,_:=a.journeyPlan(r,replacement);a.audit(r.Context(),u,"journey_rerouted","journey",id,true,map[string]any{"replacementPlanId":replacement});return map[string]any{"journeyId":id,"replanStatus":"replaced","replacementPlanId":replacement,"replacementJourney":rp},201,nil}
func (a *App) splitJourney(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){if e:=a.require(u,"dispatcher");e!=nil{return nil,0,e};if e:=needKey(in);e!=nil{return nil,0,e};id:=str(in,"journeyId");ver:=int(number(in,"expectedPlanVersion",0));if _,e:=a.checkVersion(r,id,ver);e!=nil{return nil,0,e};selected:=stringsFrom(in["sampleIds"]);if len(selected)==0{return nil,0,&apiError{409,"invalid_split","At least one sample is required"}};old,_:=a.journeyPlan(r,id);all:=stringsFrom(old["sampleIds"]);remain:=[]string{};set:=map[string]bool{};for _,x:=range selected{set[x]=true};for _,x:=range all{if !set[x]{remain=append(remain,x)}};if len(remain)==0{return nil,0,&apiError{409,"invalid_split","Cannot split every sample"}};nid:=uuid();tx,_:=a.db.Begin(r.Context());_,_=tx.Exec(r.Context(),"update labflow.journeys set sample_ids=$2,plan_version=plan_version+1 where id=$1",id,jsonMap(remain));_,_=tx.Exec(r.Context(),`insert into labflow.journeys(id,parent_id,route_mode,status,estimated_delivery_at,sample_ids,stops) select $2,id,route_mode,'planned',estimated_delivery_at,$3,stops from labflow.journeys where id=$1`,id,nid,jsonMap(selected));_,_=tx.Exec(r.Context(),"update labflow.samples set active_journey_id=$2 where active_journey_id=$1 and id=any($3)",id,nid,selected);_,_=tx.Exec(r.Context(),"update labflow.assignments set journey_id=$2 where journey_id=$1 and sample_id=any($3)",id,nid,selected);_ =tx.Commit(r.Context());p1,_:=a.journeyPlan(r,id);p2,_:=a.journeyPlan(r,nid);return map[string]any{"journey":p1,"splitJourney":p2},201,nil}
func (a *App) mergeJourneys(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){if e:=a.require(u,"dispatcher");e!=nil{return nil,0,e};if e:=needKey(in);e!=nil{return nil,0,e};target:=str(in,"targetJourneyId");if _,e:=a.checkVersion(r,target,int(number(in,"expectedPlanVersion",0)));e!=nil{return nil,0,e};sources:=stringsFrom(in["sourceJourneyIds"]);if len(sources)==0{return nil,0,&apiError{409,"invalid_merge","Source journeys required"}};tx,_:=a.db.Begin(r.Context());for _,s:=range sources{var ids []byte;if tx.QueryRow(r.Context(),"update labflow.journeys set status='merged' where id=$1 and status not in ('completed','cancelled') returning sample_ids",s).Scan(&ids)!=nil{return nil,0,&apiError{409,"invalid_merge","Source journey is not active"}};var list []string;_=json.Unmarshal(ids,&list);for _,sid:=range list{_,_=tx.Exec(r.Context(),"update labflow.journeys set sample_ids=sample_ids||to_jsonb($2::text),plan_version=plan_version+1 where id=$1",target,sid);_,_=tx.Exec(r.Context(),"update labflow.samples set active_journey_id=$2 where id=$1",sid,target);_,_=tx.Exec(r.Context(),"update labflow.assignments set journey_id=$2 where sample_id=$1 and status not in ('completed')",sid,target)}};_ =tx.Commit(r.Context());p,e:=a.journeyPlan(r,target);return p,201,e}
func (a *App) disruption(_ http.ResponseWriter,r *http.Request,u *User,in map[string]any)(any,int,*apiError){if e:=a.require(u,"dispatcher");e!=nil{return nil,0,e};if e:=needKey(in);e!=nil{return nil,0,e};did:=uuid();resource:=str(in,"resourceId");rows,_:=a.db.Query(r.Context(),`select distinct s.id,s.active_journey_id from labflow.samples s join labflow.assignments a on a.sample_id=s.id where s.status not in ('received','cancelled') and (a.worker_id::text=$1 or a.from_location_id::text=$1 or a.to_location_id::text=$1 or a.node_id::text=$1 or a.laboratory_id::text=$1)`,resource);samples,replacements:=[]string{},[]string{};if rows!=nil{for rows.Next(){var sid string;var jid *string;_=rows.Scan(&sid,&jid);samples=append(samples,sid);if jid!=nil{replacements=append(replacements,*jid)}};rows.Close()};status:="not_required";if len(samples)>0{status="exception";_,_=a.db.Exec(r.Context(),"update labflow.samples set status='exception',exception=$2 where id=any($1)",samples,jsonMap(map[string]any{"reason":"network_disruption","resourceId":resource}))};a.audit(r.Context(),u,"disruption_reported",str(in,"resourceType"),resource,true,map[string]any{"disruptionId":did});return map[string]any{"disruptionId":did,"affectedSampleIds":samples,"replacementPlanIds":[]string{},"replanStatus":status},201,nil}
