{"command":"create","path":"/workspace/frontend/src/App.tsx","file_text":"import {useEffect,useMemo,useRef,useState} from 'react'
import maplibregl from 'maplibre-gl'
import {Protocol} from 'pmtiles'
import {Activity,AlertTriangle,ArrowRight,Beaker,Box,Building2,ChevronDown,Clock3,FileSearch,History,LayoutDashboard,LogOut,MapPin,Menu,Network,PackageCheck,Plus,RefreshCw,Route,Search,ShieldCheck,Truck,Users,X} from 'lucide-react'

type Json=Record<string,any>
const labels:Record<string,string>={administrator:'Administrator',dispatcher:'Dispatcher',requester:'Requester',collection_professional:'Collection professional',delivery_partner:'Relay courier',node_handler:'Node handler',laboratory_team:'Laboratory intake'}
const tokenKey='labflow_session'
async function api(path:string,body?:Json,method='POST'){const token=localStorage.getItem(tokenKey);const res=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});const json=await res.json();if(!res.ok)throw new Error(json.error||'Request failed');return json.data}
function fmt(value?:string){if(!value)return 'Not recorded';return new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
function statusClass(s=''){return /exception|expired|cancelled|unavailable/.test(s)?'danger':/received|completed|available|serviceable/.test(s)?'success':/offered|pending|planned/.test(s)?'warning':'info'}

function Login({onLogin}:{onLogin:()=>void}){const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();setError('');setBusy(true);try{const d=await api('authenticate-user',{username,password});localStorage.setItem(tokenKey,d.sessionToken);onLogin()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <main className="login"><section className="login-story"><div className="brand brand-light"><span><Beaker/></span> LabFlow</div><div className="story-copy"><p className="eyebrow">Clinical logistics, connected</p><h1>Every sample.<br/>Every handoff.<br/><em>Accounted for.</em></h1><p>Coordinate certified collection, protected transport, and laboratory receipt through one trusted chain of custody.</p></div><div className="story-stats"><div><ShieldCheck/><b>Verified</b><span>custody events</span></div><div><Activity/><b>Live</b><span>network status</span></div><div><Clock3/><b>On time</b><span>deadline control</span></div></div></section><section className="login-panel"><form onSubmit={submit} className="login-form"><div className="mobile-brand"><Beaker/> LabFlow</div><p className="eyebrow teal">Secure access</p><h2>Welcome back</h2><p className="muted">Sign in to continue to your operations workspace.</p>{error&&<div className="form-error" role="alert"><AlertTriangle/>{error}</div>}<label>Username<input aria-label="Username" autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} placeholder="Enter your username" required/></label><label>Password<input aria-label="Password" type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password" required/></label><button className="primary wide" disabled={busy}>{busy?<><RefreshCw className="spin"/>Signing in…</>:<>Sign in <ArrowRight/></>}</button><p className="secure-note"><ShieldCheck/>Protected clinical operations environment</p></form></section></main>}

function LocalMap({operations}:{operations:Json}){const el=useRef<HTMLDivElement>(null);useEffect(()=>{if(!el.current)return;const protocol=new Protocol();maplibregl.addProtocol('pmtiles',protocol.tile);const map=new maplibregl.Map({container:el.current,center:[77.5946,12.9716],zoom:10,attributionControl:false,style:{version:8,sources:{local:{type:'vector',url:'pmtiles:///maps/bangalore.pmtiles'}},layers:[{id:'background',type:'background',paint:{'background-color':'#e9eeeb'}},{id:'water',type:'fill',source:'local','source-layer':'water',paint:{'fill-color':'#b9d9df'}},{id:'landuse',type:'fill',source:'local','source-layer':'landuse',paint:{'fill-color':'#dce8dc','fill-opacity':.55}},{id:'roads',type:'line',source:'local','source-layer':'roads',paint:{'line-color':'#ffffff','line-width':1.4}},{id:'buildings',type:'fill',source:'local','source-layer':'buildings',paint:{'fill-color':'#d1d6d2','fill-outline-color':'#c2c9c4'}}]}});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'bottom-right');for(const l of operations.locations||[]){new maplibregl.Marker({color:l.functions?.laboratory?'#d06b47':'#147d76'}).setLngLat([l.coordinate.longitude,l.coordinate.latitude]).setPopup(new maplibregl.Popup().setHTML(`<strong>${l.name}</strong><br>${l.active?'Active':'Inactive'}`)).addTo(map)}for(const w of operations.workers||[]){if(w.latestLocation)new maplibregl.Marker({color:'#183a3a',scale:.75}).setLngLat([w.latestLocation.longitude,w.latestLocation.latitude]).addTo(map)}return()=>{map.remove();maplibregl.removeProtocol('pmtiles')}},[operations]);return <div className="map-wrap"><div ref={el} className="map" aria-label="Live operations map using local map tiles"/><div className="map-legend"><span><i className="node-dot"/>Node</span><span><i className="lab-dot"/>Laboratory</span><span><i className="worker-dot"/>Worker</span></div></div>}
function Metric({icon,title,value,note,tone='teal'}:{icon:React.ReactNode,title:string,value:number|string,note:string,tone?:string}){return <article className="metric"><div className={'metric-icon '+tone}>{icon}</div><div><span>{title}</span><strong>{value}</strong><small>{note}</small></div></article>}
function Overview({data}:{data:Json}){const o=data.operations||{};const active=(o.samples||[]).filter((x:Json)=>!['received','cancelled'].includes(x.status)).length;return <><header className="page-head"><div><p className="eyebrow teal">Network command</p><h1>Good {new Date().getHours()<12?'morning':'afternoon'}, {data.user.fullName||data.user.username}</h1><p>Here’s what is happening across your sample network right now.</p></div><button className="outline"><RefreshCw/>Refresh network</button></header><section className="metrics"><Metric icon={<Beaker/>} title="Active samples" value={active} note={`${(o.samples||[]).length} total tracked`}/><Metric icon={<Truck/>} title="Available workers" value={(o.workers||[]).filter((x:Json)=>x.available).length} note={`${(o.workers||[]).length} in network`} tone="navy"/><Metric icon={<Building2/>} title="Active locations" value={(o.locations||[]).filter((x:Json)=>x.active).length} note={`${(o.connections||[]).filter((x:Json)=>x.active).length} live routes`} tone="amber"/><Metric icon={<AlertTriangle/>} title="Open exceptions" value={(o.exceptions||[]).length} note="Requires attention" tone="coral"/></section><section className="grid-main"><article className="panel map-panel"><div className="panel-head"><div><h2>Live operations</h2><p>Locations, routes and field teams</p></div><span className="live"><i/>Live</span></div><LocalMap operations={o}/></article><article className="panel"><div className="panel-head"><div><h2>Attention queue</h2><p>Items that may need action</p></div></div><div className="attention-list">{(o.exceptions||[]).slice(0,5).map((x:Json)=><div className="attention" key={x.sampleId}><span className="alert-icon"><AlertTriangle/></span><div><b>Sample exception</b><p>{x.sampleId.slice(0,8)} · {x.status}</p></div><button aria-label="View exception"><ArrowRight/></button></div>)}{!(o.exceptions||[]).length&&<Empty icon={<ShieldCheck/>} title="Network is clear" text="No open exceptions require attention."/>}</div></article></section><section className="panel categories"><div className="panel-head"><div><h2>Operations monitor</h2><p>Current network categories</p></div></div><div className="category-grid"><Category icon={<Beaker/>} n={(o.samples||[]).length} name="Samples"/><Category icon={<Users/>} n={(o.workers||[]).length} name="Workers"/><Category icon={<Building2/>} n={(o.locations||[]).length} name="Locations"/><Category icon={<Route/>} n={(o.routes||[]).length} name="Journeys"/><Category icon={<PackageCheck/>} n={(o.handoffs||[]).length} name="Handoffs"/><Category icon={<AlertTriangle/>} n={(o.exceptions||[]).length} name="Exceptions"/></div></section></>}
function Category({icon,n,name}:{icon:React.ReactNode,n:number,name:string}){return <div className="category">{icon}<strong>{n}</strong><span>{name}</span></div>}
function Empty({icon,title,text}:{icon:React.ReactNode,title:string,text:string}){return <div className="empty">{icon}<b>{title}</b><p>{text}</p></div>}

function Work(){const [work,setWork]=useState<Json>({pending:[],inProgress:[],completed:[]});const [tab,setTab]=useState('inProgress');const [loading,setLoading]=useState(true);async function load(){setLoading(true);try{setWork(await api('list-role-work',{}))}finally{setLoading(false)}}useEffect(()=>{load()},[]);const tabs=[['pending','Pending'],['inProgress','Current work'],['completed','Past work']];return <><header className="page-head"><div><p className="eyebrow teal">Assignments</p><h1>My work</h1><p>Review offers, active assignments, and completed work.</p></div></header><div className="tabs" role="tablist">{tabs.map(([id,label])=><button role="tab" aria-selected={tab===id} onClick={()=>setTab(id)} key={id}>{label}<span>{work[id]?.length||0}</span></button>)}</div><section className="panel table-panel">{loading?<div className="loading"><RefreshCw className="spin"/>Loading work…</div>:work[tab]?.length?<div className="work-list">{work[tab].map((x:Json)=><WorkCard key={x.assignmentId||x.sampleId||x.journeyId} item={x} reload={load}/>)}</div>:<Empty icon={<Box/>} title="Nothing here yet" text={tab==='completed'?'Completed work will appear here.':'No work is currently assigned in this category.'}/>}</section></>}
function WorkCard({item,reload}:{item:Json,reload:()=>void}){const [busy,setBusy]=useState(false);async function accept(){setBusy(true);try{await api('accept-assignment',{assignmentId:item.assignmentId,idempotencyKey:crypto.randomUUID()});reload()}finally{setBusy(false)}}return <article className="work-card"><div className="work-symbol">{item.kind==='transport'?<Truck/>:item.kind==='sample'?<Beaker/>:<PackageCheck/>}</div><div className="work-main"><div><span className={'badge '+statusClass(item.status)}>{item.status.replaceAll('_',' ')}</span><small>{item.kind}</small></div><h3>{item.assignmentId?'Assignment '+item.assignmentId.slice(0,8):item.sampleId?'Sample '+item.sampleId.slice(0,8):'Journey '+item.journeyId.slice(0,8)}</h3><p>{item.sampleId&&`Sample ${item.sampleId.slice(0,8)}`}{item.deliveryDeadline&&` · Due ${fmt(item.deliveryDeadline)}`}</p></div>{item.status==='offered'&&<button className="primary" disabled={busy} onClick={accept}>Accept</button>}<button className="icon-btn" aria-label="View work details"><ArrowRight/></button></article>}

function Samples({bootstrap}:{bootstrap:Json}){const samples=bootstrap.requesterSamples||bootstrap.operations?.samples||[];const [selected,setSelected]=useState<Json|null>(null);const [detail,setDetail]=useState<Json|null>(null);async function open(s:Json){setSelected(s);try{setDetail(await api('read-sample-lifecycle',{sampleId:s.sampleId}))}catch{setDetail(null)}}return <><header className="page-head"><div><p className="eyebrow teal">Custody tracking</p><h1>Samples</h1><p>Current location, holder, route progress, and complete history.</p></div></header><section className="panel table-panel"><div className="table-tools"><div className="search"><Search/><input aria-label="Search samples" placeholder="Search sample or request ID"/></div><span>{samples.length} samples</span></div>{samples.length?<div className="data-list">{samples.map((s:Json)=><button className="sample-row" onClick={()=>open(s)} key={s.sampleId}><span className="sample-icon"><Beaker/></span><span><b>{s.sampleId.slice(0,8).toUpperCase()}</b><small>{s.requestId?'Request '+s.requestId.slice(0,8):'Tracked sample'}</small></span><span><b>Last update</b><small>{fmt(s.locationRecordedAt)}</small></span><span><b>Freshness</b><small className={s.locationStale?'stale':'fresh'}>{s.locationStale?'Location stale':'Up to date'}</small></span><span className={'badge '+statusClass(s.status)}>{s.status}</span><ArrowRight/></button>)}</div>:<Empty icon={<Beaker/>} title="No samples yet" text="Samples will appear after a collection request is created."/>}</section>{selected&&<Drawer title={'Sample '+selected.sampleId.slice(0,8).toUpperCase()} close={()=>{setSelected(null);setDetail(null)}}>{detail?<SampleDetail data={detail}/>:<div className="loading"><RefreshCw className="spin"/>Loading lifecycle…</div>}</Drawer>}</>}
function SampleDetail({data}:{data:Json}){return <div className="detail"><div className="detail-status"><span className={'badge '+statusClass(data.status)}>{data.status}</span>{data.exception&&<span className="badge danger">Exception flagged</span>}</div><div className="detail-grid"><div><small>Current custodian</small><b>{data.currentHolderId?.slice(0,8)||'Not assigned'}</b></div><div><small>Last location update</small><b>{fmt(data.locationRecordedAt)}</b></div><div><small>Location freshness</small><b className={data.locationStale?'stale':'fresh'}>{data.locationStale?'Stale':'Current'}</b></div><div><small>Completed legs</small><b>{data.completedLegIds?.length||0}</b></div></div>{data.exception&&<div className="exception-box"><AlertTriangle/><div><b>Handling exception</b><p>{data.exception.reason||'Review required'}</p></div></div>}<h3>Status timeline</h3><div className="timeline">{data.timeline?.map((e:Json,i:number)=><div className="timeline-item" key={e.eventId}><i/><div><b>{e.action.replaceAll('_',' ')}</b><p>{fmt(e.occurredAt)} · {e.role.replaceAll('_',' ')}</p></div>{i===data.timeline.length-1&&<span>Latest</span>}</div>)}{!data.timeline?.length&&<p className="muted">No lifecycle events recorded.</p>}</div></div>}
function Drawer({title,close,children}:{title:string,close:()=>void,children:React.ReactNode}){return <div className="drawer-backdrop" onMouseDown={e=>e.currentTarget===e.target&&close()}><aside className="drawer" role="dialog" aria-label={title}><header><div><p className="eyebrow teal">Details</p><h2>{title}</h2></div><button className="icon-btn" onClick={close} aria-label="Close details"><X/></button></header>{children}</aside></div>}

function Audit(){const [query,setQuery]=useState('');const [result,setResult]=useState<Json>({entries:[],total:0});const [loading,setLoading]=useState(false);async function search(e?:React.FormEvent){e?.preventDefault();setLoading(true);try{setResult(await api('search-audit-trail',{query,limit:50,offset:0,order:'newest_first'}))}finally{setLoading(false)}}useEffect(()=>{search()},[]);return <><header className="page-head"><div><p className="eyebrow teal">Immutable record</p><h1>Audit trail</h1><p>Search sign-ins, permissions, custody, routes, capacity and completion.</p></div></header><section className="panel table-panel"><form className="audit-search" onSubmit={search}><div className="search"><Search/><input aria-label="Search audit history" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search action or entity ID"/></div><button className="primary">Search records</button></form><div className="audit-meta">{result.total} records · newest first</div>{loading?<div className="loading"><RefreshCw className="spin"/>Searching audit history…</div>:<div className="audit-list">{result.entries.map((e:Json)=><div className="audit-row" key={e.auditId}><span className={'audit-mark '+(e.success?'ok':'bad')}>{e.success?<ShieldCheck/>:<AlertTriangle/>}</span><div><b>{e.action.replaceAll('_',' ')}</b><p>{e.entityType} · {e.entityId.slice(0,16)}</p></div><span><b>{e.role.replaceAll('_',' ')}</b><small>{e.actorId.slice(0,8)}</small></span><time>{fmt(e.occurredAt)}</time></div>)}</div>}</section></>}

function RequestForm({close,onDone}:{close:()=>void,onDone:()=>void}){const [sampleTypeId,setType]=useState('');const [lat,setLat]=useState('12.9716');const [lon,setLon]=useState('77.5946');const [deadline,setDeadline]=useState('');const [error,setError]=useState('');const [result,setResult]=useState<Json|null>(null);async function check(e:React.FormEvent){e.preventDefault();setError('');if(!sampleTypeId||!deadline){setError('Choose a sample type and delivery deadline.');return}try{const d=await api('check-serviceability',{origin:{latitude:Number(lat),longitude:Number(lon)},originType:'home',sampleTypeId,requestedAt:new Date().toISOString(),deliveryDeadline:new Date(deadline).toISOString()});setResult(d)}catch(e){setError((e as Error).message)}}return <div className="modal-backdrop"><form className="modal" onSubmit={check}><header><div><p className="eyebrow teal">New collection</p><h2>Check serviceability</h2></div><button type="button" className="icon-btn" onClick={close}><X/></button></header><p className="muted">This dry run checks the network without creating work or reserving capacity.</p>{error&&<div className="form-error" role="alert"><AlertTriangle/>{error}</div>}<label>Sample type ID<input aria-label="Sample type ID" value={sampleTypeId} onChange={e=>setType(e.target.value)} placeholder="Paste sample type UUID"/></label><div className="form-split"><label>Latitude<input type="number" step="any" value={lat} onChange={e=>setLat(e.target.value)}/></label><label>Longitude<input type="number" step="any" value={lon} onChange={e=>setLon(e.target.value)}/></label></div><label>Delivery deadline<input aria-label="Delivery deadline" type="datetime-local" value={deadline} onChange={e=>setDeadline(e.target.value)}/></label>{result&&<div className={'service-result '+(result.serviceable?'yes':'no')}><b>{result.serviceable?'Serviceable':'Not serviceable'}</b><span>{result.reason.replaceAll('_',' ')}</span></div>}<footer><button type="button" className="outline" onClick={close}>Cancel</button><button className="primary">Check network</button></footer></form></div>}

function Shell({data,reload,signout}:{data:Json,reload:()=>void,signout:()=>void}){const [page,setPage]=useState('overview');const [roleOpen,setRoleOpen]=useState(false);const [mobile,setMobile]=useState(false);const [request,setRequest]=useState(false);const role=data.user.activeRole;const dispatcher=['administrator','dispatcher'].includes(role);const requester=role==='requester';const nav=useMemo(()=>[{id:'overview',label:'Overview',icon:<LayoutDashboard/>},{id:'work',label:'My work',icon:<Box/>},{id:'samples',label:'Samples',icon:<Beaker/>},...(dispatcher?[{id:'network',label:'Network',icon:<Network/>},{id:'audit',label:'Audit trail',icon:<FileSearch/>}]:[])],[dispatcher]);async function switchRole(r:string){await api('select-active-role',{role:r});setRoleOpen(false);setPage('overview');reload()}return <div className="app"><aside className={'sidebar '+(mobile?'open':'')}><div className="brand"><span><Beaker/></span>LabFlow</div><button className="close-mobile" onClick={()=>setMobile(false)}><X/></button><nav>{nav.map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>{setPage(n.id);setMobile(false)}}>{n.icon}<span>{n.label}</span></button>)}</nav><div className="side-foot"><div className="support"><ShieldCheck/><div><b>Chain protected</b><span>All systems operational</span></div></div><button onClick={signout}><LogOut/>Sign out</button></div></aside><div className="workspace"><header className="topbar"><button className="mobile-menu" onClick={()=>setMobile(true)}><Menu/></button><div className="crumb">Operations <span>/</span> <b>{nav.find(n=>n.id===page)?.label}</b></div><div className="top-actions">{requester&&<button className="primary compact" onClick={()=>setRequest(true)}><Plus/>New request</button>}<div className="role-picker"><button aria-label="Switch active role" aria-expanded={roleOpen} onClick={()=>setRoleOpen(!roleOpen)}><span className="avatar">{(data.user.fullName||data.user.username).slice(0,2).toUpperCase()}</span><span><b>{data.user.fullName||data.user.username}</b><small>{labels[role]||'Select role'}</small></span><ChevronDown/></button>{roleOpen&&<div className="role-menu"><small>Work as</small>{data.user.roles.map((r:string)=><button className={r===role?'selected':''} onClick={()=>switchRole(r)} key={r}>{labels[r]}{r===role&&<ShieldCheck/>}</button>)}</div>}</div></div></header><main className="content">{page==='overview'&&<Overview data={data}/>} {page==='work'&&<Work/>}{page==='samples'&&<Samples bootstrap={data}/>} {page==='network'&&<><header className="page-head"><div><p className="eyebrow teal">Network map</p><h1>Locations & routes</h1><p>Live view backed exclusively by supplied local PMTiles assets.</p></div></header><section className="panel full-map"><LocalMap operations={data.operations||{}}/></section></>} {page==='audit'&&<Audit/>}</main></div>{request&&<RequestForm close={()=>setRequest(false)} onDone={()=>{setRequest(false);reload()}}/>}</div>}

export default function App(){const [data,setData]=useState<Json|null>(null);const [loading,setLoading]=useState(!!localStorage.getItem(tokenKey));const [logged,setLogged]=useState(!!localStorage.getItem(tokenKey));async function load(){setLoading(true);try{setData(await api('ui/bootstrap',undefined,'GET'));setLogged(true)}catch{localStorage.removeItem(tokenKey);setLogged(false);setData(null)}finally{setLoading(false)}}useEffect(()=>{if(logged)load()},[logged]);if(!logged)return <Login onLogin={()=>setLogged(true)}/>;if(loading||!data)return <div className="splash"><div className="brand"><span><Beaker/></span>LabFlow</div><RefreshCw className="spin"/><p>Preparing your workspace…</p></div>;if(data.user.roleSelectionRequired)return <div className="role-gate"><div className="brand"><span><Beaker/></span>LabFlow</div><ShieldCheck/><h1>Choose your working role</h1><p>Your permissions and work queue use the role you select.</p><div>{data.user.roles.map((r:string)=><button className="role-card" onClick={async()=>{await api('select-active-role',{role:r});load()}} key={r}><span>{labels[r]}</span><ArrowRight/></button>)}</div></div>;return <Shell data={data} reload={load} signout={()=>{localStorage.removeItem(tokenKey);setLogged(false)}}/>}
