{"command":"create","path":"/workspace/frontend/src/styles.css","file_text":"@import url('data:text/css,');
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#173332;background:#f5f7f4;font-synthesis:none;--ink:#173332;--muted:#6f7f7b;--teal:#147d76;--teal-dark:#0d5e59;--navy:#203f50;--line:#dde5df;--paper:#fff;--cream:#f5f7f4;--coral:#d06b47;--amber:#c79235;--shadow:0 10px 35px rgba(27,58,55,.08)}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.6;cursor:wait}.login{min-height:100vh;display:grid;grid-template-columns:1.12fr .88fr;background:#fff}.login-story{position:relative;overflow:hidden;padding:42px 7vw;color:#fff;background:linear-gradient(145deg,rgba(12,55,53,.97),rgba(13,93,87,.9)),radial-gradient(circle at 70% 30%,#29948c,#0d3c3a)}.login-story:before,.login-story:after{content:"";position:absolute;border:1px solid rgba(255,255,255,.1);border-radius:50%;width:520px;height:520px;right:-180px;top:-120px}.login-story:after{width:350px;height:350px;top:auto;right:80px;bottom:-210px}.brand{font-family:Georgia,serif;font-weight:700;font-size:23px;display:flex;align-items:center;gap:10px;letter-spacing:-.5px}.brand span{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:var(--teal);color:#fff}.brand svg{width:21px}.brand-light span{background:rgba(255,255,255,.14)}.story-copy{max-width:620px;margin-top:16vh}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:11px;font-weight:800;margin:0 0 12px}.eyebrow.teal{color:var(--teal)}.story-copy h1{font:500 clamp(46px,5.2vw,78px)/.98 Georgia,serif;letter-spacing:-.045em;margin:0 0 30px}.story-copy h1 em{color:#83d1c7;font-style:italic}.story-copy>p:last-child{font-size:17px;line-height:1.7;color:#d3e3df;max-width:540px}.story-stats{display:flex;gap:46px;position:absolute;left:7vw;bottom:50px}.story-stats div{display:grid;grid-template-columns:25px auto;column-gap:10px}.story-stats svg{grid-row:1/3;width:21px;color:#83d1c7}.story-stats b{font-size:13px}.story-stats span{font-size:11px;color:#abc6c1}.login-panel{display:grid;place-items:center;padding:40px}.login-form{width:min(420px,100%)}.mobile-brand{display:none}.login-form h2{font:500 42px/1 Georgia,serif;margin:0 0 12px;letter-spacing:-.03em}.muted{color:var(--muted)}.login-form>p.muted{margin-bottom:34px}.login-form label,.modal label{display:grid;gap:8px;font-size:13px;font-weight:700;margin:18px 0}.login-form input,.modal input{padding:14px 15px;border:1px solid #cfd9d3;border-radius:8px;background:#fbfcfa;outline:none;transition:.2s}.login-form input:focus,.modal input:focus{border-color:var(--teal);box-shadow:0 0 0 3px rgba(20,125,118,.1)}.primary,.outline{border:0;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:11px 16px;font-size:13px;font-weight:750}.primary{background:var(--teal);color:#fff}.primary:hover{background:var(--teal-dark)}.primary svg,.outline svg{width:16px}.wide{width:100%;padding:14px;margin-top:12px}.outline{border:1px solid var(--line);background:#fff;color:var(--ink)}.compact{padding:9px 13px}.secure-note{color:#82908c;display:flex;align-items:center;justify-content:center;gap:7px;font-size:11px;margin-top:24px}.secure-note svg{width:15px}.form-error{padding:12px;border-radius:7px;color:#993f2d;background:#fff0eb;display:flex;gap:8px;align-items:center;font-size:13px;margin:18px 0}.form-error svg{width:18px}.app{display:flex;min-height:100vh}.sidebar{position:fixed;z-index:20;inset:0 auto 0 0;width:238px;background:#123c3a;color:#d8e6e2;display:flex;flex-direction:column;padding:27px 17px}.sidebar>.brand{padding:0 10px 28px;color:#fff}.sidebar nav{display:grid;gap:4px;border-top:1px solid rgba(255,255,255,.1);padding-top:20px}.sidebar nav button,.side-foot>button{border:0;background:transparent;color:#b9cfca;border-radius:7px;padding:11px 12px;display:flex;gap:12px;align-items:center;text-align:left;font-size:13px;font-weight:650}.sidebar nav button:hover,.sidebar nav button.